  delete_state = #{deleteState,jdbcType=BIGINT}
WHERE id = #{id,jdbcType=VARCHAR}

UPDATE msg_template SET template_name = #{templateName,jdbcType=VARCHAR}, message_type = #{messageType,jdbcType=CHAR}, push_way = #{pushWay,jdbcType=CHAR}, title_template = #{titleTemplate,jdbcType=VARCHAR}, content_template = #{contentTemplate,jdbcType=LONGVARCHAR}, `variables` = #{variables,jdbcType=VARCHAR,typeHandler=com.uoquo.web.mybatis.handler.List2JsonTypeHandler}, description = #{description,jdbcType=VARCHAR},
is_default = #{defaulted,jdbcType=BIT},
update_user = #{updateUser,jdbcType=VARCHAR}, update_time = #{updateTime,jdbcType=TIMESTAMP} WHERE id = #{id,jdbcType=VARCHAR}


