SELECT

FROM msg_template
WHERE delete_state = 0
  AND message_type = #{messageType,jdbcType=CHAR}
  AND push_way     = #{pushWay,jdbcType=CHAR}
  AND is_default   = true


SELECT

FROM msg_template
WHERE delete_state = 0

  AND template_code LIKE CONCAT('%', #{templateCode,jdbcType=VARCHAR}, '%')


  AND template_name LIKE CONCAT('%', #{templateName,jdbcType=VARCHAR}, '%')


  AND message_type = #{messageType,jdbcType=CHAR}


  AND push_way = #{pushWay,jdbcType=CHAR}


  AND is_default = #{defaulted,jdbcType=BIT}


  AND `status` = #{status,jdbcType=CHAR}


  AND create_time BETWEEN #{createTimeStart,jdbcType=TIMESTAMP} AND #{createTimeEnd,jdbcType=TIMESTAMP}
